window.docContents[160].resolve({"/releases/#feat-full-page-search-interface":{"contents":"Pressing \"Enter\" in the search box now leads to a full-page search interface that shows more results with more context and includes checkboxes to filter the results by their semantic domain.\nAs a result, domains with custom search CSS should replace the #search-wrapper selector with the .verso-search-results class.\n\n\n","context":"Writing Documentation in Lean with Verso\u0009Release Notes\u0009Verso 4.30.0 (unreleased)","header":"Full-Page Search Interface","id":"/releases/#feat-full-page-search-interface"}});